SELECT sa.anime_id AS animeId, s.series_id AS seriesId, s.title_kor_manual AS titleMan, s.title_kor AS titleKor, s.title_eng AS titleEng, s.title_rom AS titleRom, s.title_nat AS titleNat, COALESCE(NULLIF(s.cover_image_url_manual, ''), s.cover_image_url) AS coverImageUrl FROM series_anime sa JOIN series s ON s.series_id = sa.series_id WHERE sa.anime_id IN
#{animeId}
AND NOT EXISTS(SELECT 1 FROM animegenres ag WHERE ag.anime_id = sa.anime_id AND ag.genre_id = 638)
